import { z } from 'zod';

/**
 * Typed form of the CableSizer lookup tables (generated by scripts/convert-cablesizer.ts from
 * docs/reference/cablesizer_lookup_rules.json, which stays the unchanged source record).
 */

export const REVIEW_STATUS = 'awaiting engineer sign-off (OI-07)' as const;

/** One accepted alternative for a field: all given bounds must hold (AND). */
export const AlternativeSchema = z.strictObject({
  eq: z.union([z.number(), z.string()]).optional(),
  gt: z.number().optional(),
  gte: z.number().optional(),
  lt: z.number().optional(),
  lte: z.number().optional(),
});
export type Alternative = z.infer<typeof AlternativeSchema>;

/** Table cell value. Source expressions such as "0.82 / 3" are resolved at conversion time. */
export const CellValueSchema = z.union([
  z.number(),
  /** Parallel conductors, e.g. CableSizer earth conductor "2 * 150" = 2 x 150 mm2. */
  z.strictObject({
    kind: z.literal('parallel'),
    conductors: z.number().int(),
    sizeMm2: z.number(),
  }),
  /** A note instead of a number, e.g. "Refer Transformer Datasheet". */
  z.strictObject({ kind: z.literal('text'), text: z.string() }),
]);
export type CellValue = z.infer<typeof CellValueSchema>;

export const ReviewFlagSchema = z.strictObject({
  status: z.literal(REVIEW_STATUS),
  /** Where the issue is recorded, e.g. "V-15". */
  reference: z.string(),
  note: z.string(),
});
export type ReviewFlag = z.infer<typeof ReviewFlagSchema>;

export const RowSchema = z.strictObject({
  /** Index of the rule in the source file's `rules` array. */
  source: z.number().int().nonnegative(),
  /** Field name -> accepted alternatives (OR). Every listed field must match (AND). Empty = always. */
  match: z.record(z.string(), z.array(AlternativeSchema).min(1)),
  value: CellValueSchema,
  /** Original text when the source value was an expression or note. */
  sourceExpression: z.string().optional(),
  /** CableSizer "else" branch: the value used when no specific row matched. */
  fallback: z.literal(true).optional(),
  review: ReviewFlagSchema.optional(),
});
export type Row = z.infer<typeof RowSchema>;

export const FunctionTableSchema = z.strictObject({
  args: z.array(
    z.strictObject({ name: z.string(), type: z.enum(['number', 'string', 'number|string']) }),
  ),
  rows: z.array(RowSchema).min(1),
  knownIssues: z.array(ReviewFlagSchema).optional(),
});
export type FunctionTable = z.infer<typeof FunctionTableSchema>;

export const LookupTablesSchema = z.strictObject({
  format: z.literal('neuromep.cablesizer-lookup/1'),
  source: z.strictObject({ path: z.string(), sha256: z.string(), ruleCount: z.number().int() }),
  evaluation: z.string(),
  functions: z.record(z.string(), FunctionTableSchema),
});
export type LookupTables = z.infer<typeof LookupTablesSchema>;
